def rand_event(i):
    r = random.random()
    eid = f"e{i}"
    if r < 0.15:
        return json.dumps({"event_id": eid, "type": "CANCEL", "order_id": f"o{random.randint(1, 12)}"})
    side = random.choice(["BUY", "SELL"])
    ot = random.choice(["LIMIT", "LIMIT", "MARKET"])
    q = random.randint(1, 6)
    obj = {"event_id": eid, "type": "ADD", "order_id": f"o{random.randint(1, 14)}",
           "side": side, "order_type": ot, "quantity": q}
    if ot == "LIMIT":
        obj["price"] = random.choice([95, 99, 100, 101, 105])
    elif random.random() < 0.3:
        obj["price"] = None
    # occasionally inject malformed-but-old-schema-legal weirdness / dups
    return json.dumps(obj, separators=(",", ":"))

bad_lines = ["{", "not json", "123", "null", "[]",
             json.dumps({"event_id": "x", "type": "ADD"}),
             json.dumps({"event_id": 7, "type": "CANCEL", "order_id": "o1"})]

mismatch = 0
for trial in range(200):
    lines = []
    for i in range(random.randint(1, 40)):
        if random.random() < 0.08:
            lines.append(random.choice(bad_lines))
        else:
            lines.append(rand_event(i + random.randint(0, 10**9)))
    stream = "\n".join(lines) + "\n"
    outs = []
    for path in ["/tmp/obe_baseline", "/mnt/c/dbsvace/vo1/A/task002"]:
        p = subprocess.run([sys.executable, "-m", "order_book_engine.cli", "replay"],
                           input=stream.encode(), capture_output=True,
                           env={"PYTHONPATH": path, "PATH": "/usr/bin:/bin"})
        outs.append(p.stdout)
    if outs[0] != outs[1]:
        mismatch += 1
        print("MISMATCH trial", trial)
        print(stream)
        if mismatch >= 3:
            break
print("done, mismatches:", mismatch)
